CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1), json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(
 id TEXT PRIMARY KEY, username TEXT NOT NULL COLLATE NOCASE UNIQUE,
 display_name TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', password TEXT NOT NULL,
 owner INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL CHECK(status IN('pending','approved','rejected','suspended')),
 avatar INTEGER NOT NULL DEFAULT 0, totp TEXT, totp_pending TEXT, totp_step INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS sole_owner ON users(owner) WHERE owner=1;
CREATE UNIQUE INDEX IF NOT EXISTS unique_email ON users(email COLLATE NOCASE) WHERE email!='';
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, csrf TEXT NOT NULL, created INTEGER NOT NULL, expires INTEGER NOT NULL, label TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS groups(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
INSERT OR IGNORE INTO groups(id,name) VALUES('members','Members');
CREATE TABLE IF NOT EXISTS memberships(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, group_id TEXT NOT NULL REFERENCES groups(id) ON DELETE CASCADE, PRIMARY KEY(user_id,group_id));
CREATE TABLE IF NOT EXISTS resources(id TEXT PRIMARY KEY, kind TEXT NOT NULL, name TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'restricted' CHECK(visibility IN('public','members','restricted')));
CREATE TABLE IF NOT EXISTS grants(resource TEXT NOT NULL REFERENCES resources(id) ON DELETE CASCADE, subject TEXT NOT NULL, subject_kind TEXT NOT NULL CHECK(subject_kind IN('user','group')), role TEXT NOT NULL DEFAULT 'access', PRIMARY KEY(resource,subject,subject_kind,role));
CREATE TABLE IF NOT EXISTS shares(id TEXT PRIMARY KEY REFERENCES resources(id) ON DELETE CASCADE, root TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS routes(id TEXT PRIMARY KEY REFERENCES resources(id) ON DELETE CASCADE, hostname TEXT NOT NULL UNIQUE, upstream TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, gated INTEGER NOT NULL DEFAULT 0, service TEXT NOT NULL DEFAULT '', service_kind TEXT NOT NULL DEFAULT 'none');
CREATE TABLE IF NOT EXISTS apps(id TEXT PRIMARY KEY REFERENCES resources(id) ON DELETE CASCADE, manifest TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, hostname TEXT NOT NULL DEFAULT '', config TEXT NOT NULL DEFAULT '{}', port INTEGER NOT NULL, secret TEXT NOT NULL, previous TEXT, error TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS clients(id TEXT PRIMARY KEY, secret TEXT NOT NULL, resource TEXT NOT NULL REFERENCES resources(id) ON DELETE CASCADE, redirect TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS codes(id TEXT PRIMARY KEY, client TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, redirect TEXT NOT NULL, challenge TEXT NOT NULL, nonce TEXT NOT NULL, scope TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tokens(id TEXT PRIMARY KEY, client TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, scope TEXT NOT NULL, expires INTEGER NOT NULL, family TEXT NOT NULL, kind TEXT NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS token_families(id TEXT PRIMARY KEY,expires INTEGER NOT NULL,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS resets(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL, activation INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS recovery_codes(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, hash TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS gateway_sessions(id TEXT PRIMARY KEY, resource TEXT NOT NULL REFERENCES resources(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS gateway_flows(id TEXT PRIMARY KEY, resource TEXT NOT NULL REFERENCES resources(id) ON DELETE CASCADE, verifier TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT, actor TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL, created INTEGER NOT NULL);
